"""Handle forex and market data endpoints (OANDA removed - using MT4)."""
from .apirequest import APIRequest
from .decorators import dyndoc_insert, endpoint
from .responses.forexlabs import responses
from abc import abstractmethod


class MarketDataAPI(APIRequest):
    """MarketDataAPI - abstract base class to handle market data endpoints (replaces OANDA ForexLabs)."""

    ENDPOINT = ""
    METHOD = "GET"

    @abstractmethod
    @dyndoc_insert(responses)
    def __init__(self):
        """Instantiate a MarketDataAPI request instance."""
        endpoint = self.ENDPOINT.format()
        super(MarketDataAPI, self).__init__(endpoint,
                                        method=self.METHOD)


@endpoint("mt4/market/calendar")
class Calendar(MarketDataAPI):
    """Calendar.

    Get economic calendar information from MT4 data source.
    """

    @dyndoc_insert(responses)
    def __init__(self, params):
        """Instantiate a Calendar request.

        Parameters
        ----------
        params : dict (required)
            query params to send.


        >>> import trading_platform
        >>> import trading_platform.endpoints.marketdata as market
        >>> client = trading_platform.API(access_token=...)
        >>> params = {"currency": "USD", "impact": "high"}
        >>> r = market.Calendar(params=params)
        >>> client.request(r)
        >>> print(r.response)

        Output::

            {_v3_market_calendar_resp}

        """
        super(Calendar, self).__init__()
        self.params = params


